        if "version" in response.text.lower():
            print("PROVEN: IDOR allows access to administrative version details without authentication")
        else:
            print("WEAK: Response doesn't contain expected version info")
    else:
        print(f"FAILED: Status code {response.status_code}")

except Exception as e:
